        "RBRACKET"
    | RBRACE ->
        "RBRACE"
    | QUESTION ->
        "QUESTION"
    | PROFILE ->
        "PROFILE"
    | PORT ->
        "PORT"
    | PIPEPIPE ->
        "PIPEPIPE"
    | PIPE ->
        "PIPE"
